 const match = router([...itemRoutes, ...batchRoutes, ...orderRoutes, ...kitchenRoutes, ...planningRoutes, ...safetyRoutes]);

+function requestLanguage(headers) {
+  const header = Object.entries(headers).find(([name]) => name.toLowerCase() === "accept-language")?.[1];
+  if (typeof header !== "string") return config.defaultLanguage;
+  let language = config.defaultLanguage;
+  let bestQuality = 0;
+  for (const entry of header.split(",")) {
+    const [tag, ...parameters] = entry.trim().toLowerCase().split(";");
+    const base = tag.trim().match(/^(en|ko)(?:-[a-z0-9]{1,8})*$/)?.[1];
+    if (!base) continue;
+    let quality = 1;
+    for (const parameter of parameters) {
+      const value = parameter.trim();
+      if (/^q\s*=/.test(value)) {
+        const match = value.match(/^q\s*=\s*(0(?:\.\d{0,3})?|1(?:\.0{0,3})?)$/);
+        quality = match ? Number(match[1]) : 0;
+      }
+    }
+    if (quality > bestQuality) {
+      language = base;
+      bestQuality = quality;
+    }
+  }
+  return language;
+}
